using UnityEngine;

namespace TheLastFortress
{
    /// <summary>Asset references the bootstrap needs. Generated by the editor setup script.</summary>
    [CreateAssetMenu(menuName = "The Last Fortress/Prototype Content", fileName = "PrototypeContent")]
    public sealed class PrototypeContent : ScriptableObject
    {
        public PrototypeDefinitionsAsset definitions;

        [Header("Entity prefabs")]
        public GameObject keepPrefab;
        public GameObject wallPrefab;
        public GameObject towerPrefab;
        public GameObject gruntPrefab;

        [Header("Materials")]
        public Material grass;
        public Material water;
        public Material timberShadow;
        public Material overlay;
        public Material arrow;

        [Header("Layouts")]
        public TextAsset winningLayout;
        public TextAsset losingLayout;
        public TextAsset stressLayout;

        public GameObject PrefabFor(BuildingKind kind)
        {
            switch (kind)
            {
                case BuildingKind.Keep: return keepPrefab;
                case BuildingKind.Wall: return wallPrefab;
                default: return towerPrefab;
            }
        }
    }
}
